import type { CharId, SkillId, Speed } from './data';
import { CHARACTERISTICS } from './data';

/**
 * Profili dei PNG dalla Guida del Gamemaster. Servitori: sconfitti alla prima
 * Ferita. Bruti e Mostruosità: il tracciato dice cosa succede a ogni Ferita.
 * Campioni: tirano sulla tabella delle Ferite come i personaggi.
 */

export type NpcType = 'Servitore' | 'Bruto' | 'Campione' | 'Mostruosità';

export interface NpcAttack {
  name: string;
  range: string;
  dice: number;
  target: number;
  /** null: niente Danno (infligge una Condizione o un effetto) */
  damage: number | null;
  hands?: 1 | 2;
  traits?: string;
  ignoresArmour?: boolean;
}

export interface NpcProtection {
  skill: 'Atletica' | 'Difesa' | 'Furtività';
  dice: number;
  target: number;
  shield?: boolean;
}

export interface Npc {
  id: string;
  name: string;
  group: string;
  type: NpcType;
  chars: Record<CharId, number>;
  speed: Speed;
  /** null: non subisce Danni (sciami) */
  resilience: number | null;
  armoured: boolean;
  /** Bruti e Mostruosità: soglie di Ferite ed effetti; l’ultima è "Sconfitto" */
  track?: { at: string; effect: string }[];
  /** quante Ferite lo sconfiggono (1 per i Servitori) */
  maxWounds: number | null;
  skills: Partial<Record<SkillId, number>>;
  /** valore di tutte le altre Abilità */
  other: number;
  attacks: NpcAttack[];
  protection: NpcProtection[];
  abilities: { name: string; text: string }[];
  /** Livello da Mago e incantesimi conosciuti */
  mage?: { level: number; spells: { name: string; vm: number; text: string }[] };
  gear?: string;
}

const SK: Record<string, SkillId> = {
  Mischia: 'mischia', Difesa: 'difesa', Tiro: 'tiro', Lancio: 'lancio', Muscoli: 'muscoli', Lavoro: 'lavoro', Sopravvivenza: 'sopravvivenza',
  Tempra: 'tempra', Percezione: 'percezione', Destrezza: 'destrezza', Atletica: 'atletica', Furtività: 'furtivita', Volontà: 'volonta',
  Memoria: 'memoria', Comando: 'comando', Fascino: 'fascino',
};

/** "Mischia 4, Volontà 3, Altro 2" */
function skills(s: string): { skills: Partial<Record<SkillId, number>>; other: number } {
  const out: Partial<Record<SkillId, number>> = {};
  let other = 2;
  for (const part of s.split(',')) {
    const m = /^\s*(.+?)\s+(\d+)\s*$/.exec(part);
    if (!m) continue;
    if (m[1] === 'Altro') other = Number(m[2]);
    else if (SK[m[1]!]) out[SK[m[1]!]!] = Number(m[2]);
  }
  return { skills: out, other };
}

/** "Nome|Portata|3d/4|Danno|mani|tratti" (Danno "-" se non ne fa) */
function attack(s: string): NpcAttack {
  const [name, range, pool, dmg, hands, traits] = s.split('|');
  const [dice, target] = pool!.replace('d', '').split('/').map(Number);
  const tr = traits?.trim() || undefined;
  return {
    name: name!.trim(), range: range!.trim(), dice: dice!, target: target!,
    damage: dmg && dmg.trim() !== '-' ? Number(dmg) : null,
    hands: hands === '2' ? 2 : hands === '1' ? 1 : undefined,
    traits: tr,
    ignoresArmour: tr ? /ignora l.armatura/i.test(tr) : undefined,
  };
}

/** "Atletica 3/2, Difesa 4/4 scudo" */
function protection(s: string): NpcProtection[] {
  return s.split(',').map((p) => {
    const m = /(Atletica|Difesa|Furtività)\s+(\d+)\/(\d+)(\s*scudo)?/.exec(p)!;
    return { skill: m[1] as NpcProtection['skill'], dice: Number(m[2]), target: Number(m[3]), shield: !!m[4] || undefined };
  });
}

const slug = (s: string) =>
  s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[’']/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

interface Def {
  name: string;
  group: string;
  type: NpcType;
  chars: string;
  speed: Speed;
  res: number | null;
  armoured?: boolean;
  track?: [string, string][];
  skills: string;
  attacks: string[];
  prot: string;
  abilities: [string, string][];
  mage?: { level: number; spells: [string, number, string][] };
  gear?: string;
}

function npc(d: Def): Npc {
  const values = d.chars.trim().split(/\s+/).map(Number);
  const chars = Object.fromEntries(CHARACTERISTICS.map((c, i) => [c, values[i] ?? 0])) as Record<CharId, number>;
  const track = d.track?.map(([at, effect]) => ({ at, effect }));
  const last = track?.[track.length - 1]?.at;
  const maxWounds = d.res === null ? null : d.type === 'Servitore' ? 1 : d.type === 'Campione' ? null : last ? Number(/(\d+)\D*$/.exec(last)?.[1] ?? 1) : 1;
  return {
    id: slug(d.name), name: d.name, group: d.group, type: d.type, chars, speed: d.speed, resilience: d.res, armoured: !!d.armoured,
    track, maxWounds, ...skills(d.skills), attacks: d.attacks.map(attack), protection: protection(d.prot),
    abilities: d.abilities.map(([name, text]) => ({ name, text })),
    mage: d.mage ? { level: d.mage.level, spells: d.mage.spells.map(([name, vm, text]) => ({ name, vm, text })) } : undefined,
    gear: d.gear,
  };
}

