export const NPCS: Npc[] = DEFS.map(npc);
export const NPC_GROUPS = [...new Set(NPCS.map((n) => n.group))];
export const getNpc = (id: string | null | undefined): Npc | undefined => NPCS.find((n) => n.id === id);

/** What the host needs to settle attacks against this creature (null for swarms). */
export function npcPool(n: Npc) {
  if (n.resilience === null) return null;
  const score = (p: NpcProtection) => p.dice * p.target;
  const best = [...n.protection].sort((a, b) => score(b) - score(a))[0] ?? { skill: 'Atletica', dice: n.chars.ag, target: n.skills.atletica ?? n.other };
  // shots: only a shield lets Difesa stop them
  const ranged = n.protection.filter((p) => p.skill !== 'Difesa' || p.shield).sort((a, b) => score(b) - score(a))[0] ?? best;
  return {
    type: n.type,
    resilience: n.resilience,
    toughness: n.chars.r,
    armoured: n.armoured,
    melee: { dice: best.dice, target: best.target },
    ranged: { dice: ranged.dice, target: ranged.target },
    wounds: 0,
    maxWounds: n.maxWounds,
    track: n.track,
    monster: n.type === 'Mostruosità' || undefined,
  };
}
